overview=dict(status='usable',rationale='Representative formation, authority transitions, their connection and necessary support paths have been read. Remaining local continuations and deeper variants are explicit; no experimental finding is claimed.',formation=dict(explanation='Node serializes incoming proposals, ticks and messages, or caller serializes RawNode. A leader assigns term/index and emits replication. Followers match predecessor history and defer positive append support until persistence. Leader self support also waits for storage. Match values are aggregated over incoming and, if joint, outgoing majority; commitment requires the selected index to belong to the current term. Appends propagate commit and heartbeats bound it by the recipient Match. Ready delivers committed history; applying and applied remain distinct until caller completion.',behavior_ids=['B-form','B-follow','B-persist','B-apply'],fact_ids=['F-committed','F-config'],source_ids=['S-node','S-reset','S-response','S-tracker','S-quorum','S-commit','S-ready','S-advance']),context=dict(explanation='Eligible voters campaign only after committed configuration work is applied. Real elections increment term and record durable votes; pre-vote probes without incrementing local term. Log freshness and voter quorums qualify authority. Higher-term ordinary traffic steps down; lower-term traffic is generally discarded. Candidate accepts only its current vote phase. Leader transfer pauses proposals until target catches up and TimeoutNow starts a forced election; timeout aborts transfer. Quorum loss can step down. Membership application changes voter eligibility and may remove the leader.',behavior_ids=['B-authority','B-config','B-persist'],fact_ids=['F-config'],source_ids=['S-election','S-step','S-roles','S-response','S-config']),connection=dict(explanation='Term/role and installed configuration determine which support the leader consumes. Reset discards vote tallies, remote Match estimates and acknowledged read queue but preserves log/commit history; new leaders append a current-term no-op, and log freshness carries committed history through elections. Old-term append support is ignored. Old storage completions cannot stabilize overwritten entries, while snapshot/application completions concern already decided history and remain meaningful across terms. Restoration reconstructs history and configuration before eligibility. Pending pre-commit reads are a distinct queue whose lifetime needs investigation. Membership updates may recompute commit, whereas application completion can propose automatic joint exit; these follow-up effects are not interchangeable.',behavior_ids=['B-authority','B-form','B-config','B-apply','B-recover','B-read','B-persist'],fact_ids=['F-committed','F-config'],source_ids=['S-reset','S-step','S-start','S-recovery','S-config','S-autoleave','S-release']),core_gaps=[],open_details=['Automatic joint-exit retry after transfer rejection and timeout.','Legal reachability of first current-term commitment through configuration application with pending reads.','Pre-commit read queue lifetime across authority changes.','Detailed snapshot/flow-control retries, storage implementation mutation boundaries and client cancellation paths remain open.'])
surfaces=[dict(entry_point='raft.appliedTo automatic joint exit',disposition='mapped',behavior_ids=['B-apply'],reason='An application callback proposes automatic exit; transfer may reject it and timeout only clears transfer. Need establish retry ownership and a legal history with no later application.',source_ids=['S-autoleave','S-election','S-proposal'],high_consequence=True),dict(entry_point='raft.switchToConfig commitment and queued reads',disposition='mapped',behavior_ids=['B-config','B-read'],reason='Commit follow-up differs from MsgAppResp path. Campaign exclusion of unapplied committed changes may rule out the suspicious history; investigate before constructing.',source_ids=['S-config','S-response','S-election'],high_consequence=False),dict(entry_point='raft.pendingReadIndexMessages across reset',disposition='deferred',reason='reset replaces readOnly but does not visibly clear the pre-commit queue; inspect request identity and subsequent release before alleging a defect.',source_ids=['S-reset','S-proposal','S-release'],high_consequence=True),dict(entry_point='MemoryStorage mutation and compaction',disposition='deferred',reason='Storage interface read; concrete mutation and compaction methods remain to be inspected.',source_ids=['S-storage'],high_consequence=True)]
m=dict(version=1,target_profile=dict(system_boundary='Captured go.etcd.io/raft module implementing one Raft group per Node/RawNode; caller provides transport, durable persistence, ticks and state-machine application. In-repository storage and configuration helpers remain inside investigation scope.',protocol_contexts=['term and role','log prefix','applied membership including joint quorums'],external_interfaces=['Node','RawNode','Storage','Ready/Advance','ordered local storage messages'],ownership=['Node serializes raft state; RawNode requires caller serialization. Disk/network/application effects belong to embedding caller under documented duties.'],variants=['PreVote','CheckQuorum','ReadOnlySafe/ReadOnlyLeaseBased','AsyncStorageWrites','simple/joint membership'],source_ids=['S-api','S-async','S-node','S-storage']),activities=activities,behaviors=bs,facts=facts,surfaces=surfaces,core_overview=overview)
